import type { BrainEngine } from './engine.ts';

/**
 * JTT fork: take_proposal_evidence is always the newest migration, so every upstream release that adds
 * migrations collides with it. Generated by AGENT-HUB skills/mac-mini-ops/scripts/gbrain-auto-upgrade.py
 * (edit the template there, not here).
 *
 * The previous deploy (v0.60.641.0) stamped production at 298 with JTT's evidence migration.
 * Upstream now owns up to v318; JTT's migration is v319.
 * A brain still stamped 298 has NOT applied upstream v298..v318: rewind the stamp to
 * 297 once (guarded by the config marker) so runMigrations applies them; v319 is idempotent,
 * so the existing evidence column is a no-op.
 *
 * Returns the stamp after rewind, or null when no rewrite was needed.
 */
export const JTT_TAKE_PROPOSAL_EVIDENCE_VERSION = 319;
export const JTT_PREVIOUS_STAMP = 298;
export const JTT_REWIND_MARKER = 'jtt_rewound_from_298';

export async function rewindJttTakeProposalCollision(engine: BrainEngine): Promise<number | null> {
  if (JTT_PREVIOUS_STAMP >= JTT_TAKE_PROPOSAL_EVIDENCE_VERSION) return null;
  const current = await engine.getConfig('version');
  if (current !== String(JTT_PREVIOUS_STAMP)) return null;
  if (await engine.getConfig(JTT_REWIND_MARKER)) return null;

  const [evidence] = await engine.executeRaw<{ ok: boolean }>(
    `SELECT EXISTS (
       SELECT 1 FROM information_schema.columns
       WHERE table_schema = 'public' AND table_name = 'take_proposals' AND column_name = 'evidence'
     ) AS ok`,
  );
  if (!evidence?.ok) return null;

  await engine.setConfig(JTT_REWIND_MARKER, new Date().toISOString());
  await engine.setConfig('version', String(JTT_PREVIOUS_STAMP - 1));
  process.stderr.write(
    `  [jtt] schema stamp ${JTT_PREVIOUS_STAMP} was JTT take_proposal_evidence; rewound to ${JTT_PREVIOUS_STAMP - 1} so upstream v${JTT_PREVIOUS_STAMP}+ can apply\n`,
  );
  return JTT_PREVIOUS_STAMP - 1;
}
